$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[8] = "To find out more about an ability, hold your mouse over its icon for a couple of seconds.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[9] = "Good job, Sonny. Keep going, and stay alert. There will be more of them ahead.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[10] = "What are these things, anyway? They look horrid, decayed - and the smell is nauseating!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[11] = "I reckon they used to be the ship\'s crew...but, not anymore.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[12] = "What\'s happened to them?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[13] = "It\'s complicated and we\'re running out of time! I\'ll tell you everything when we\'re off this ship!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[14] = "You\'re outnumbered. Don\'t worry, though! You have the strongest weapon.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[15] = "This pipe?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[16] = "No, I\'m talking about your brain! Think! Attack the weakest one first, and defend yourself when you can!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[17] = "That green one in front of us is toxic. Watch out for its poison.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[18] = "But, you\'re blind, how do you even know...?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[19] = "Don\'t get all technical on me, Sonny. Just be glad I told you.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[21] = "Hey, I can see the speed boat hangar. It\'s right up ahead!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[22] = "I think I can hear helicopters, Sonny.. it must be the rescue team!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[23] = "Finally! You\'re here! I thought we would die on this forsaken ship!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[24] = "Take them out, boys. We don\'t need any witnesses.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[25] = "What...?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[26] = "Louis! This is NOT a good day to be shooting my friends!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[27] = "Hey, look at that! That one just talked!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[28] = "So what? That \'thing\' is no different from the rest of them. Just do your job, soldier!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[29] = "Hey Uh... do you know where I can find the nearest pay phone?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[30] = "Uruhugh!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[31] = "Whoa, take it easy!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[33] = "What did I do to deserve this?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[35] = "Leave...horrors...ahead...";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[37] = "You are not welcome here!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[38] = "There\'s another! Shoot him down.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[39] = "By all means, try!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[40] = "Es spricht?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[41] = "Uruhugh!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[42] = "There he is! He\'s wearing the stolen combat suit!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[43] = "HEY! Hey, you! I don\'t know if you noticed, but I\'m slightly outnumbered here! Could you help me out? ";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[44] = "Can\'t say I\'m too fond of these bastards myself.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[45] = "Focus fire! Everyone take the same target!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[46] = "Shoot to kill!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[47] = "Thanks for helping me back there, bud. I\'m Veradux.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[48] = "They call me Sonny. I can\'t remember my real name.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[49] = "The Sensei does not approve of your presence here! We\'ve been sent to kill you!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[50] = "I got your back, Sonny! Rip them open! ";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[51] = "No...further...";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[52] = "You tread our sacred grounds. You refuse to leave. For that, I shall break you.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[55] = "You\'re kickin\' ass! We make a heck of a team.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[56] = "So. How long do you plan to stick around?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[57] = "Uh... Until death do us part!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[58] = "You\'re hilarious.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[59] = "This is Shaman land! I\'ll cut you down in the name of my tribe!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[60] = "Argh! Something is wrong... My head!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[61] = "You alright Sonny?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[62] = "Yeah I\'ll be alright.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[63] = "Sonny... I\'m starting to feel it too...";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[64] = "What\'s happening? Are we dying?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[65] = "Not physically... But our minds are decaying.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[66] = "Oh, brilliant. That doesn\'t sound painful at all.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[67] = "The \'Council\' hunts you, infidels! Back away!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[68] = "That\'s about as far as you\'ll go!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[69] = "Ha ha! Nice outfit.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[70] = "It sure looks better than yours!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[71] = "Hey! Who\'s side are you on?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[72] = "No not these guys again... I can\'t ... I... Argh!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[73] = "Someone is playing with our minds... Stay focused!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[74] = "How did I know we\'d find them here as well?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[75] = "Hey, go for the weaker one first, or we\'ll never get them down.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[76] = "We, the council, deem you dead!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[77] = "You have trespassed here, and killed our brethren!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[78] = "Your blood will pay for your misdeeds!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[79] = "Haha... Who, us? We wouldn\'t hurt a fly!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[80] = "Well, would you look at that! The last Shaman. How sad. Let\'s kill it!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[81] = "The Baron awaits you, children.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[101] = "Is he the one behind these mind games?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[102] = "He is your new master. You shall obey.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[103] = "Obey THIS, you twat!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[82] = "More Zombies! Let\'s fry them! We\'ll meet with the Paladin later.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[83] = "We\'re wasting time, the Paladin needs our help to take down the Baron!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[94] = "Reinforcements? That Baron must be one mean zombie.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[84] = "Welcome to the darkness, my children...become one with me and all beings.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[85] = "Finally, my reinforcements! It\'s good to see you\'re alive and well!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[93] = "Just shut up and nod, Sonny. Shut up and nod.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[86] = "Wait, wasn\'t there supposed to be three of you?";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[87] = "The Baron is gone. Let\'s kill this whoopy superhero and leave!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[88] = "But... why? He helped us-";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[89] = "Sonny. To them, we\'re vermin...we\'re monsters.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[92] = "Now we can either be alive monsters, or dead monsters. You choose.";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[90] = "What is this...? You would turn on me?!";
$$o(KrinLang?.ENGLISH?.BATTLESPEECH)[91] = "You shall pay for this deception!";
