$$o(KrinLang?.GERMAN?.MENU)[5] = "Gegenstand hier drauflegen, um ihn zu verkaufen.";
$$o(KrinLang?.GERMAN?.MENU)[6] = "Klick auf Gegenstände, um sie zu kaufen:";
$$o(KrinLang?.GERMAN?.MENU)[7] = "Du hast Fähigkeitspunkte zur Verfügung! Hier klicken um zu lernen, wie man sie benutzt.";
$$o(KrinLang?.GERMAN?.MENU)[8] = "Du kannst mit deinen Fähigkeitspunkten neue Fähigkeiten erlernen! Für weitere Informationen über eine Fähigkeit, halte den Mauszeiger über sie.";
$$o(KrinLang?.GERMAN?.MENU)[9] = "Jetzt kannst du dein Eigenschaftspunkt benutzen, um eine Eigenschaft zu verbessern.";
