$$o(KrinLang?.GERMAN).BATTLESPEECH = new Array();
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[0] = "Ich mag blind sein, aber dieser Geruch ist unverwechselbar. Kannst du ihn besiegen?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[1] = "Na ja… ich glaub… ich glaub schon! Ugh…ich fühl mich überhaupt nicht gut.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[2] = "Dass wird schon nachlassen. Konzentrier dich!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[3] = "Beachte den grauen \'Ring\' unten in der Mitte. Warte bis er blau wird.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[4] = "Wenn der Ring blau ist, klick auf deinen Gegner um ihn ins Visier zu nehmen. Deine Fähigkeiten werden um ihn herum angezeigt.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[5] = "Er sieht nicht gerade sehr erfreut aus.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[6] = "Er ist wütend. Du musst dich verteidigen! Achtung!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[7] = "Klick diese Runde dich selber, so dass du eine defensive Fähigkeit benutzen kannst.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[8] = "Für mehr Information über eine Fähigkeit, halte einfach die Maus über ihr Symbol und warte einen Moment.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[9] = "Gut gemacht, Sonny. Hier entlang, und bleib auf der Hut! Wir werden noch mehr von ihnen begegnen.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[10] = "Was sind diese Kreaturen eigentlich? Sie sehen schrecklich, verdorben... und der Geruch ist ekelhaft!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[11] = "Ich schätze mal, sie waren die Crew dieses Schiffes... sie waren es.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[12] = "Was ist mit ihnen passiert?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[13] = "Dass ist kompliziert, und wir haben keine Zeit! Ich erzähl dir alles sobald wir von diesem Schiff entkommen sind!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[14] = "Du bist in der Minderheit. Aber keine Angst, du hast die beste Waffe!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[15] = "Dieses Rohr?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[16] = "Nein du Trottel, dein Gehirn! Denk nach! Greif zuerst den schwächeren an, und verteidige dich immer, wenn du kannst. ";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[17] = "Der Grüne vor uns ist giftig. Pass auf sein Gift auf.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[18] = "Aber, du bist doch blind, woher weißt du…...";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[19] = "Jetzt nimm doch nicht alles so streng! Sei einfach froh, dass ich’s dir gesagt habe.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[21] = "Hey, Ich kann den Beiboothangar sehen! Es ist direkt voraus.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[22] = "Ich glaube ich höre Helikopter, Sonny... es muss das Rettungsteam sein!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[23] = "Endlich seid ihr hier! Ich dachte wir würden auf diesem verlassenen Schiff verrecken!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[24] = "Setzt sie außer Gefecht, Jungs! Wir können uns keine Zeugen leisten.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[25] = "Was…?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[26] = "Louis! Heute ist kein guter Tag, meine Freunde umzubringen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[27] = "Hey, guckt euch dass mal an! Der da hat gerade gesprochen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[28] = "Na und? Das Monster ist genau so, wie alle anderen auch. Erledige deine Pflicht, Soldat!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[29] = "Hey ehm… weißt du zufälligerweise wo ich dass nächste Telefon finden kann?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[30] = "Uruhugh!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[31] = "Whoa, mach doch kein Stress!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[33] = "Was habe ich getan, um dieses Schicksal zu verdienen??";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[35] = "Verlass...diesen Ort...Horror…";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[37] = "Du bist hier nicht willkommen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[38] = "Da ist noch einer! Erschießt ihn";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[39] = "Versucht‘s doch!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[40] = "Es spricht?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[41] = "Uruhugh!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[42] = "Dass ist er! Er trägt einen gestohlenen Tarnanzug!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[43] = "HEY! Hey, du da! Vielleicht ist es dir nicht aufgefallen, aber ich bin etwas in der Minderheit. Kannste mir mal helfen?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[44] = "Na ja, ich habe diese Typen auch nicht gerade lieb...";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[45] = "Alle auf einen zielen! Gibt’s ihm! Feuer!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[46] = "Shoot to kill!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[47] = "Danke für deine Hilfe Kumpel. Ich bin Veradux.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[48] = "Man nennt mich Sonny. An meinen echten Namen erinnere ich mich nicht.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[49] = "Der Sensei bewilligt eure Präsenz nicht! Wir wurden von ihm geschickt um euch umzulegen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[50] = "Ich unterstütze dich schon! Reiß sie offen Sonny!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[51] = "Nicht...weiter...";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[52] = "Ihr betretet unseren heiligen Ort. Ihr weigert euch zu gehen. Dafür werde ich euch brechen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[55] = "Wir machen jeden fertig! Wir sind doch nen geiles Team!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[56] = "Und? Wie lange hast du vor in der Nähe zu bleiben?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[57] = "Uh...Bis der Tot uns scheide!!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[58] = "Ha..ha, das ist ja zum totlachen.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[59] = "Dies ist Schamanenland! Ich gebe euch nen kurzen Haarschnitt!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[60] = "Arrgh! Irgendwas ist los...mein Kopf!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[61] = "Geht’s dir gut, Sonny?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[62] = "Ja, wird schon.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[63] = "Sonny...ich merke es auch langsam...";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[64] = "Was geschieht mit uns? Sterben wir?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[65] = "Nicht physisch… aber unsere Gehirne verwesen.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[66] = "Ach so! Wunderbar, dass hört sich ja überhaupt nicht schmerzlich an.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[67] = "Der Rat jagd euch, Ungläubige! Rennt weg!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[68] = "Na ja, weiter wirst du nicht kommen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[69] = "Haha! Cooles Outfit.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[70] = "Es sieht auf jeden Fall besser aus, als deins!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[71] = "Hey! Ich dachte du wärst auf meiner Seite!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[72] = "Nicht schon wieder diese Typen...ich kann...ich...argh!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[73] = "Jemand spielt mit unseren Gedanken...konzentrier dich!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[74] = "Woher wusste ich dass wir diese Typen auch hier finden würden?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[75] = "Geh zuerst auf den schwächeren, oder wir besiegen sie nie.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[76] = "Wir, der Rat, erachten euch als tot!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[77] = "Ihr seid hier eingedrungen, und habt unsere Brüder umgebracht!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[78] = "Euer Blut wird für eure Sünden büßen.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[79] = "Haha…Wer, wir? Wir würden noch nicht mal ner Fliege was zuleide tun!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[80] = "Na guck mal da! Der letzte Schamane. Wie traurig. Wir legen ihn um!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[81] = "Der Baron wartet auf euch, Kinder.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[101] = "Ist er der Typ der uns die ganze Zeit Kopfschmerzen macht?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[102] = "Er ist euer neuer Herr. Ihr werdet euch unterwerfen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[103] = "Unterwerf DASS, du Trottel!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[82] = "Noch mehr Zombies, komm, wir erledigen sie! Wir können den Paladin auch noch später treffen.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[83] = "Wir vergeuden Zeit, der Paladin braucht unsere Hilfe um den Baron anzugreifen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[94] = "Unsere Hilfe? Dieser Baron muss ne ziemlich harte Nuss sein.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[84] = "Willkommen in der Finsternis, meine Kinder...werdet eins mit mir und allen Lebewesen.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[85] = "Endlich, meine Verstärkung. Gut euch wieder zu sehen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[93] = "Halt einfach die Klappe, Sonny, und nick freundlich. Halt die Klappe und nick.";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[86] = "Moment, gab’s nicht drei von euch?";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[87] = "Der Baron ist tot. Lass uns diesen Möchtegern Superhelden erledigen und uns vom Acker machen!";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[88] = "Aber...warum? Er hat uns geholfen–";
$$o(KrinLang?.GERMAN?.BATTLESPEECH)[89] = "Sonny. Zu dehnen sind wir nichts, schlimmer als nichts, wir sind Monster.";
