$$o(KrinLang?.GERMAN?.NAVTITLE)[0] = "Informationen";
$$o(KrinLang?.GERMAN?.NAVTEXT)[0] = "Das Spiel wurde gespeichert!";
$$o(KrinLang?.GERMAN?.NAVTITLE)[1] = "Ein Rettungsring";
$$o(KrinLang?.GERMAN?.NAVTEXT)[1] = "Da passt nur einer rein! Willst du wirklich den armen behinderten Mann der dir das Leben gerettet hat verlassen, du egoistischer Trottel? Versuch lieber ein Beiboot zu finden, um zu entkommen.";
$$o(KrinLang?.GERMAN?.NAVTITLE)[2] = "Ein wunderschöner Sonnenuntergang";
$$o(KrinLang?.GERMAN?.NAVTEXT)[2] = "Der schönste und romantischste Sonnenuntergang den du je gesehen hast...Schade dass du nicht bleiben kannst um ihn dir anzugucken.";
$$o(KrinLang?.GERMAN?.NAVTITLE)[3] = "Land";
$$o(KrinLang?.GERMAN?.NAVTEXT)[3] = "Land in Sicht! Wenn du ein Beiboot finden kannst, kannst du wahrscheinlich entkommen.";
$$o(KrinLang?.GERMAN?.NAVTITLE)[5] = "Der Geist eines Fischers";
$$o(KrinLang?.GERMAN?.NAVTEXT)[5] = "Ein kopfloser Fischer scheint hier zu fischen...";
$$o(KrinLang?.GERMAN?.NAVTITLE)[6] = "White November";
$$o(KrinLang?.GERMAN?.NAVTEXT)[6] = "Das Schiff brennt in der Ferne. Armer, armer Louis...";
$$o(KrinLang?.GERMAN?.NAVTITLE)[7] = "Ein altes Schild";
$$o(KrinLang?.GERMAN?.NAVTEXT)[7] = "Auf dem Schild steht:  ‚Hew. 80km.‘ Was zum Teufel ist Hew? Lass uns es einfach folgen.";
$$o(KrinLang?.GERMAN?.NAVTITLE)[8] = "Klippen";
$$o(KrinLang?.GERMAN?.NAVTEXT)[8] = "Das Schild zeigt in diese Richtung. Hoffentlich führt es zu einem besseren Ort.";
$$o(KrinLang?.GERMAN?.NAVTITLE)[9] = "Dorf";
$$o(KrinLang?.GERMAN?.NAVTEXT)[9] = "Ihr könnt beide gerne hier bleiben, aber hinter den Bergen gibt es eine größere Stadt. Um dort hinzugelangen müsst ihr den Schamanenrat besiegen; denen gehört die Region!";
$$o(KrinLang?.GERMAN?.NAVTITLE)[10] = "Ein blauer See";
$$o(KrinLang?.GERMAN?.NAVTEXT)[10] = "Es sieht nicht sehr stabil aus, außerdem seid ihr zu zweit. Such lieber ein Beiboot um zu entkommen.";
$$o(KrinLang?.GERMAN?.NAVTITLE)[11] = "Die Letzte Zone";
$$o(KrinLang?.GERMAN?.NAVTEXT)[11] = "Glückwunsch! Du hast die letzte Zone des Spiels erreicht. Dies ist nur eine Herausforderung, und hat mit der Geschichte von Sonny nichts zu tun. Es gibt auch eine neue Spielregel: Du musst dich innerhalb einer bestimmten Zeit für dein nächsten Zug entscheiden.";
$$o(KrinLang?.GERMAN?.NAVTITLE2)[0] = "Hallo, Matrose!";
$$o(KrinLang?.GERMAN?.NAVTEXT2)[0] = "Willkommen zu  \'Sonny!\'  Dies ist ein Kampf/Strategie Spiel, aber du bist zurzeit im \'Welt\'-Modus. Hier kannst du dein Charakter individualisieren, und ihn für den nächsten Kampf ausrüsten. Die Herausforderung dieses Spiels ist prinzipiell einfach: Kämpfe bis du den Boss der Zone erreichst, besiege ihn, und du kannst eine neue Zone betreten. Um den nächsten Kampf anzufangen, klick das rote Symbol nachdem du diese Fenster geschlossen hast. Viel Spaß!";
$$o(KrinLang?.GERMAN?.NAVTITLE2)[1] = "Informationen zum Erreichen einer neuen Stufe";
$$o(KrinLang?.GERMAN?.NAVTEXT2)[1] = "Du konntest soeben deinen Charakter verbessern, weil du eine neue Stufe erreicht hast. Die Entscheidung, welche Fähigkeiten und Eigenschaften du erlernen willst ist wichtig; sie hat eine große Auswirkung auf das Spiel. Vergiss nicht, deine neuen Fähigkeiten von deinem \'Fähigkeitspool\' in die \'Actionbar\' zu holen. Manche Fähigkeiten kannst du sogar mehrmals in deiner Actionbar haben.";
$$o(KrinLang?.GERMAN?.NAVTITLE2)[2] = "Informationen zu Gegenständen und Ausrüstung";
$$o(KrinLang?.GERMAN?.NAVTEXT2)[2] = "Der letzte Feind, den du besiegt hast, hat Beute hinterlassen! Beute kannst du entweder benutzen, um dein Charakter zu verbessern, oder du kannst sie in einem Laden verkaufen (Laden sind mit einem blauen Symbol gekennzeichnet).";
$$o(KrinLang?.GERMAN?.NAVTITLE2)[3] = "Sonny";
$$o(KrinLang?.GERMAN?.NAVTEXT2)[3] = "Es sieht nicht gut aus…Ich bin auf einem Geisterstrand gestrandet, und habe nur eine dämliche Kassette. Ich sollte weiter gehen, und gucken ob ich Zivilisation finden kann. Vielleicht kann mir ja jemand helfen...";
$$o(KrinLang?.GERMAN?.NAVTITLE2)[4] = "Information";
$$o(KrinLang?.GERMAN?.NAVTEXT2)[4] = "Deine Gruppe hat ein neues Mitglied! Du kannst deine Gruppe im Inventarmenu ausrüsten und verstellen. Klick auf das Bild eines Mitglieds um es zu betrachten, shift-klick es um das Mitglied zu deinem aktiven Team hinzuzufügen bzw. entfernen. Im Moment hast du nur zwei Gruppenmitglieder, also ist der Aufbau des Teams eher unwichtig.";
$$o(KrinLang?.GERMAN?.NAVTITLE2)[5] = "Sonny";
$$o(KrinLang?.GERMAN?.NAVTEXT2)[5] = "Wir sind endlich weg von diesem Strand, jetzt stehen uns nur noch ein paar wahnsinnige Schamanen im Weg, dann haben wir Zivilisation erreicht…Ich will einfach nur dass dieser Tag zu Ende geht...";
$$o(KrinLang?.GERMAN?.NAVTITLE2)[6] = "Veradux";
$$o(KrinLang?.GERMAN?.NAVTEXT2)[6] = "Sonny, wir haben noch ein Problem…ich glaube jemand da draußen versucht uns zu kontrollieren. Ich glaub nicht, dass es ZPCI ist, die sind da unten und töten die Devourers genau wie wir. Nein, wir stehen einem ganz anderen Feind gegenüber.";
